# region: emit
def emit(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: digest
def digest(xs, limit=9):
    return [v if v <= limit else limit for v in xs[1:]]

# region: render
def render(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: gather
def gather(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return gather(fold(shape(render(digest(emit(raw))))))

